grant select on public.audit_logs to authenticated;
create policy "Administrators read active institution audit history" on public.audit_logs for select to authenticated using (public.has_role((select auth.uid()),'admin'::public.app_role) and exists (select 1 from public.institution_memberships m where m.user_id=(select auth.uid()) and m.role='admin'::public.app_role and m.status='active' and m.institution_id=sina_private.current_institution('admin'::public.app_role)) and (table_name not in ('students','grades') or exists (select 1 from public.students s where s.id=case when table_name='students' then record_id else (coalesce(new_data,old_data)->>'student_id')::uuid end and s.institution_id=sina_private.current_institution('admin'::public.app_role))));